import {Breadcrumbs, PageHeader} from '@primer/react'
import type {ReactNode} from 'react'

type NavigatePath = {
  href: string
  text: string
}

type CurrentActionPath = 'Edit role' | 'Create a role' | 'Create custom role' | 'Edit custom role'
type CurrentActionTitle = CurrentActionPath | 'Organization roles'
export function CustomRolePage({
  form,
  navigatePaths,
  currentActionPath,
  currentActionTitle,
  pageTitle,
  subheadDescription,
  subheadDescriptionLink,
}: {
  form?: ReactNode
  navigatePaths?: NavigatePath[]
  currentActionPath?: CurrentActionPath
  currentActionTitle?: CurrentActionTitle
  pageTitle: 'h1' | 'h2'
  subheadDescription?: string
  subheadDescriptionLink?: React.ReactElement
}) {
  return (
    <div>
      <div className="d-flex flex-column flex-items-start flex-self-stretch">
        <div className="width-full border-bottom color-border-default">
          {currentActionPath && (
            <Breadcrumbs>
              {navigatePaths?.map(({href, text}) => (
                <Breadcrumbs.Item key={href} href={href}>
                  {text}
                </Breadcrumbs.Item>
              ))}
              <Breadcrumbs.Item data-testid="current-action-path" selected>
                {currentActionPath}
              </Breadcrumbs.Item>
            </Breadcrumbs>
          )}
          <PageHeader className="pb-1 mb-1 mt-2">
            <PageHeader.TitleArea id="custom-role-page-header-title">
              <PageHeader.Title as={pageTitle}>{currentActionTitle || currentActionPath}</PageHeader.Title>
            </PageHeader.TitleArea>
          </PageHeader>
        </div>
        <div className="pt-2 pb-1">
          {subheadDescription}
          {subheadDescriptionLink}
        </div>
      </div>
      <div id="page-content-section">{form}</div>
    </div>
  )
}

try{ CustomRolePage.displayName ||= 'CustomRolePage' } catch {}