import {testIdProps} from '@github-ui/test-id-props'
import {TargetTypeIconMap, type TargetType} from '../../types'
import {Blankslate} from '@primer/react/experimental'

export interface PermissionsBlankslateProps {
  targetType: TargetType
}

export function PermissionsBlankslate({targetType}: PermissionsBlankslateProps) {
  const targetToMessageMap: Record<TargetType, {message: string}> = {
    Enterprise: {
      message: 'Get started by adding permissions to this role.',
    },
    Organization: {
      message:
        'Organization roles can include repository permissions, which are granted to all repositories in the organization.',
    },
    Repository: {
      message: 'Get started by adding permissions to this role.',
    },
  }

  const IconComponent = TargetTypeIconMap[targetType]

  return (
    <Blankslate size="small" spacious {...testIdProps(`permissions-blankslate-${targetType.toLowerCase()}`)}>
      <Blankslate.Visual>
        <IconComponent size="medium" {...testIdProps('permissions-blankslate-icon')} />
      </Blankslate.Visual>
      <Blankslate.Heading>No {targetType.toLowerCase()} permissions added yet</Blankslate.Heading>
      <Blankslate.Description>{targetToMessageMap[targetType].message}</Blankslate.Description>
    </Blankslate>
  )
}

try{ PermissionsBlankslate.displayName ||= 'PermissionsBlankslate' } catch {}