import {registerDataRouterApp} from '@github-ui/react-core/register-app'
import {customRolesAppBuilder} from './config/app-builder'

import {CustomEnterpriseRoles} from './routes/CustomEnterpriseRoles'
import {CustomEnterpriseOwnedOrgRoles} from './routes/CustomEnterpriseOwnedOrgRoles'
import {CustomOrgRoles} from './routes/CustomOrgRoles'
import {customOrgRolesRoute} from './routes/custom-org-roles-route'
import {customEnterpriseRolesRoute} from './routes/custom-enterprise-roles-route'
import {customEnterpriseOwnedOrgRolesRoute} from './routes/custom-enterprise-owned-org-roles-route'
import {LayoutRoute} from './routes/LayoutRoute'
import {layoutRoute} from './routes/layout-route'
import {customRepoRolesRoute} from './routes/custom-repo-roles-route'
import {CustomRepoRoles} from './routes/CustomRepoRoles'
import {customOrgRolesEditRoute} from './routes/custom-org-roles-edit-route'

export const customRolesApp = customRolesAppBuilder.createDataRouterAppFromRoutes([
  layoutRoute.toRoute({
    Component: LayoutRoute,
    children: [
      customOrgRolesRoute.toRoute({Component: CustomOrgRoles}),
      customOrgRolesEditRoute.toRoute({Component: CustomOrgRoles}),
      customEnterpriseOwnedOrgRolesRoute.toRoute({Component: CustomEnterpriseOwnedOrgRoles}),
      customEnterpriseRolesRoute.toRoute({Component: CustomEnterpriseRoles}),
      customRepoRolesRoute.toRoute({Component: CustomRepoRoles}),
    ],
  }),
])
registerDataRouterApp(customRolesApp)
