import {useParams} from '@github-ui/react-router'
import {CustomRoleForm} from '../components/CustomRoleForm'
import {testIdProps} from '@github-ui/test-id-props'
import {CustomRolePage} from '../components/CustomRolePage'
import {Link} from '@primer/react'
import {customRepoRolesRoute} from './custom-repo-roles-route'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'

export function CustomRepoRoles() {
  const {slug} = useParams<{slug: string}>()
  const basePath = customRepoRolesRoute.generatePath({slug: slug || '', action: ''})
  const payload = useRouteQuery(customRepoRolesRoute, 'mainQuery')
  const {availablePermissions, availableBaseRoles} = payload.data

  const navigatePaths = [{href: basePath, text: 'Repository roles'}]
  const currentActionPath = 'Create a role'
  const subheadDescription =
    'Roles are used to grant access and permissions for teams and members. Begin by choosing a role to inherit and adding permissions to create a role that fits your needs.'
  const subheadDescriptionLink = (
    <Link
      className="ml-1"
      href="https://docs.github.com/github/setting-up-and-managing-organizations-and-teams/repository-permission-levels-for-an-organization"
    >
      Learn more about custom repository roles.
    </Link>
  )
  return (
    <div {...testIdProps('custom-repo-roles-page')}>
      <CustomRolePage
        subheadDescription={subheadDescription}
        subheadDescriptionLink={subheadDescriptionLink}
        navigatePaths={navigatePaths}
        currentActionPath={currentActionPath}
        pageTitle="h2"
        form={
          <CustomRoleForm
            basePath={basePath}
            availablePermissions={availablePermissions}
            availableBaseRoles={availableBaseRoles}
          />
        }
      />
    </div>
  )
}

try{ CustomRepoRoles.displayName ||= 'CustomRepoRoles' } catch {}