import {useParams} from '@github-ui/react-router'
import {customEnterpriseOwnedOrgRolesRoute} from './custom-enterprise-owned-org-roles-route'
import {CustomRolePage} from '../components/CustomRolePage'
import {CustomRoleForm} from '../components/CustomRoleForm'
import {testIdProps} from '@github-ui/test-id-props'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'

export function CustomEnterpriseOwnedOrgRoles() {
  const {slug} = useParams<{slug: string}>()
  const basePath = customEnterpriseOwnedOrgRolesRoute.generatePath({slug: slug || '', action: ''})
  const payload = useRouteQuery(customEnterpriseOwnedOrgRolesRoute, 'mainQuery')
  const {availablePermissions, availableBaseRoles} = payload.data
  const actionTitle = 'Organization roles'
  return (
    <div {...testIdProps('custom-enterprise-owned-org-roles-page')}>
      <CustomRolePage
        pageTitle="h1"
        currentActionTitle={actionTitle}
        form={
          <CustomRoleForm
            basePath={basePath}
            availablePermissions={availablePermissions}
            availableBaseRoles={availableBaseRoles}
            addPermissionsText="Organization roles can include repository permissions. Repository permissions are granted to all repositories in the organization."
          />
        }
      />
    </div>
  )
}

try{ CustomEnterpriseOwnedOrgRoles.displayName ||= 'CustomEnterpriseOwnedOrgRoles' } catch {}