import {ActionList, ActionMenu} from '@primer/react'
import {BaseRoleIconMap, type BaseRole} from '../../types'
import {testIdProps} from '@github-ui/test-id-props'

interface BaseRoleMenuProps {
  available: BaseRole[]
  selected: BaseRole | undefined
  onSelect: (role: BaseRole) => void
  targetTypeName: string
}

// Capitalizes the first letter of the role name
function getBaseRoleDisplayName(role: string): string {
  return role.charAt(0).toUpperCase() + role.slice(1)
}

export function BaseRoleMenu({available, selected, onSelect, targetTypeName}: BaseRoleMenuProps) {
  if (available.length === 0) {
    return null
  }

  return (
    <ActionMenu>
      <ActionMenu.Button variant="invisible" {...testIdProps('base-role-menu-button')}>
        <span className="fgColor-muted">Base {targetTypeName} role: </span>
        <span>{getBaseRoleDisplayName(selected || available[0] || '')}</span>
      </ActionMenu.Button>
      <ActionMenu.Overlay>
        <ActionList selectionVariant="single" role="menu" aria-label="Item">
          {available.map(role => {
            const IconComponent = BaseRoleIconMap[role]
            return (
              <ActionList.Item key={role} onSelect={() => onSelect(role)} selected={role === selected}>
                <ActionList.LeadingVisual>{IconComponent && <IconComponent />}</ActionList.LeadingVisual>
                {getBaseRoleDisplayName(role)}
              </ActionList.Item>
            )
          })}
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}

try{ BaseRoleMenu.displayName ||= 'BaseRoleMenu' } catch {}