import type {Role} from '@github-ui/role-assignments/types/role-assignments'
import {
  BookIcon,
  ChecklistIcon,
  DotIcon,
  EyeIcon,
  GlobeIcon,
  OrganizationIcon,
  PencilIcon,
  RepoIcon,
  ToolsIcon,
} from '@primer/octicons-react'

export interface CustomRolePayload {
  availablePermissions: PermissionsByTargetType
  availableBaseRoles?: BaseRolesByTargetType
  role?: Role
}

export interface Permission {
  label: string
  category: string
  description: string
  baseRole?: BaseRole
}

export const TargetType = {
  Enterprise: 'Enterprise',
  Organization: 'Organization',
  Repository: 'Repository',
} as const

export const TARGET_TYPE_ORDER = [TargetType.Enterprise, TargetType.Organization, TargetType.Repository] as const

export const BaseRole = {
  None: 'none',
  Read: 'read',
  Triage: 'triage',
  Write: 'write',
  Maintain: 'maintain',
  Admin: 'admin',
} as const

export type TargetType = (typeof TargetType)[keyof typeof TargetType]
export type PermissionsByTargetType = Partial<Record<TargetType, Permission[]>>
export type RequiredPermissionsByTargetType<T extends readonly TargetType[]> = Record<T[number], Permission[]>
export type BaseRole = (typeof BaseRole)[keyof typeof BaseRole]
export type BaseRolesByTargetType = Partial<Record<TargetType, BaseRole[]>>
export type PermissionsByBaseRole = Partial<Record<BaseRole, Permission[]>>

export const TargetTypeIconMap = {
  Enterprise: GlobeIcon,
  Organization: OrganizationIcon,
  Repository: RepoIcon,
}

export const BaseRoleIconMap = {
  none: DotIcon,
  read: BookIcon,
  triage: ChecklistIcon,
  write: PencilIcon,
  maintain: ToolsIcon,
  admin: EyeIcon,
}
