import {SimpleListView} from '@github-ui/simple-list-view'
import {PermissionsBlankslate} from './PermissionsBlankslate'
import type {BaseRole, Permission, TargetType} from '../../types'
import {SimpleListItem} from '@github-ui/simple-list-view/SimpleListItem'
import {IconButton, Label, Text} from '@primer/react'
import {testIdProps} from '@github-ui/test-id-props'
import {XIcon} from '@primer/octicons-react'
import {useCallback} from 'react'

export interface PermissionsListProps {
  targetType: TargetType
  selectedFgps: Permission[]
  setSelectedFgps: (selectedFgps: Permission[]) => void
  baseRoleFgps?: Permission[]
}

export function PermissionsList({targetType, selectedFgps, setSelectedFgps, baseRoleFgps}: PermissionsListProps) {
  const removePermission = useCallback(
    (permissionToRemove: Permission) => {
      setSelectedFgps(selectedFgps.filter(fgp => fgp.label !== permissionToRemove.label))
    },
    [selectedFgps, setSelectedFgps],
  )

  // Show blankslate if no selected or base role permissions
  if (selectedFgps.length === 0 && (!baseRoleFgps || (baseRoleFgps && baseRoleFgps.length === 0))) {
    return <PermissionsBlankslate targetType={targetType} />
  }

  return (
    <div {...testIdProps('permissions-list')}>
      <SimpleListView.Items>
        {selectedFgps.map(fgp => (
          <SelectedPermissionListItem key={fgp.label} permission={fgp} onRemove={removePermission} />
        ))}
        {baseRoleFgps?.map(fgp =>
          // baseRole should always be defined for base role permissions, but we do a null check to be safe
          fgp.baseRole != null ? (
            <BaseRolePermissionListItem key={fgp.label} permission={fgp} baseRole={fgp.baseRole} />
          ) : null,
        )}
      </SimpleListView.Items>
    </div>
  )
}

function SelectedPermissionListItem({
  permission,
  onRemove,
}: {
  permission: Permission
  onRemove: (permission: Permission) => void
}) {
  return (
    <SimpleListItem>
      <SimpleListItem.Title>{permission.description}</SimpleListItem.Title>
      <SimpleListItem.TrailingActions trailingActionStyling={{align: 'center'}}>
        <Label size="small" variant="secondary">
          {permission.category}
        </Label>
        <IconButton
          aria-label={`Remove: ${permission.description}`}
          icon={XIcon}
          variant="invisible"
          tooltipDirection="n"
          size="small"
          onClick={() => onRemove(permission)}
          {...testIdProps(`remove-permission-${permission.label}`)}
        />
      </SimpleListItem.TrailingActions>
    </SimpleListItem>
  )
}

function BaseRolePermissionListItem({permission, baseRole}: {permission: Permission; baseRole: BaseRole}) {
  return (
    <SimpleListItem>
      <SimpleListItem.Title>{permission.description}</SimpleListItem.Title>
      <SimpleListItem.TrailingActions>
        <Text size="small" className="fgColor-muted">
          Inherited from {baseRole}
        </Text>
      </SimpleListItem.TrailingActions>
    </SimpleListItem>
  )
}

try{ PermissionsList.displayName ||= 'PermissionsList' } catch {}
try{ SelectedPermissionListItem.displayName ||= 'SelectedPermissionListItem' } catch {}
try{ BaseRolePermissionListItem.displayName ||= 'BaseRolePermissionListItem' } catch {}