import {useParams} from '@github-ui/react-router'
import {customOrgRolesRoute} from './custom-org-roles-route'
import {CustomRoleForm} from '../components/CustomRoleForm'
import {testIdProps} from '@github-ui/test-id-props'
import {CustomRolePage} from '../components/CustomRolePage'
import {Link} from '@primer/react'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {customOrgRolesEditRoute} from './custom-org-roles-edit-route'

export function CustomOrgRoles() {
  const {slug, role_id} = useParams<{slug: string; role_id?: string}>()
  const basePath = customOrgRolesRoute.generatePath({slug: slug || '', action: ''})
  const queryRoute = role_id ? customOrgRolesEditRoute : customOrgRolesRoute
  const payload = useRouteQuery(queryRoute, 'mainQuery')
  const {availablePermissions, availableBaseRoles, role} = payload.data
  const currentActionPath = role_id ? 'Edit role' : 'Create a role'

  const navigatePaths = [{href: basePath, text: 'Role management'}]
  const subheadDescription =
    'Organization roles are used to grant access to subsets of organization settings to teams and members. You can create up to 10 custom roles to fit your needs.'
  const subheadDescriptionLink = (
    <Link
      className="ml-1"
      href="https://docs.github.com/organizations/managing-peoples-access-to-your-organization-with-roles/about-custom-organization-roles"
    >
      Learn more about custom organization roles.
    </Link>
  )

  return (
    <div {...testIdProps('custom-org-roles-page')}>
      <CustomRolePage
        subheadDescription={subheadDescription}
        subheadDescriptionLink={subheadDescriptionLink}
        navigatePaths={navigatePaths}
        currentActionPath={currentActionPath}
        pageTitle="h2"
        form={
          <CustomRoleForm
            basePath={basePath}
            role={role}
            availablePermissions={availablePermissions}
            availableBaseRoles={availableBaseRoles}
            addPermissionsText="Organization roles can include repository permissions. Repository permissions are granted to all repositories in the organization."
          />
        }
      />
    </div>
  )
}

try{ CustomOrgRoles.displayName ||= 'CustomOrgRoles' } catch {}